// RSS feeds to monitor - CUSTOMIZE THESE
const feeds = [
  'https://simonwillison.net/atom/everything/',
  'https://www.latent.space/feed',
  'https://lilianweng.github.io/index.xml',
  'https://newsletter.pragmaticengineer.com/feed',
  'https://blog.langchain.dev/rss/',
  'https://openai.com/blog/rss.xml',
  'https://www.anthropic.com/rss.xml',
  'https://huggingface.co/blog/feed.xml'
];

return feeds.map(url => ({ json: { feed_url: url } }));

// Parse RSS/Atom and extract articles, deduplicate by URL
const xml = $input.first().json.data || '';
const articles = [];

const itemRegex = /<(item|entry)>(.*?)<\/(item|entry)>/gs;
let match;
while ((match = itemRegex.exec(xml)) !== null) {
  const item = match[2];
  const title = item.match(/<title[^>]*>(.*?)<\/title>/s)?.[1]?.replace(/<[^>]+>/g, '') || '';
  const link = item.match(/<link[^>]*href=["']([^"']+)/)?.[1] || item.match(/<link>(.*?)<\/link>/)?.[1] || '';
  const published = item.match(/<(pubDate|published|updated)>(.*?)<\//)?.[2] || '';
  const content = item.match(/<(description|content|summary)[^>]*>(.*?)<\//s)?.[2]?.replace(/<[^>]+>/g, '').slice(0, 500) || '';
  if (title && link) {
    articles.push({ json: { title, link, published, content: content.trim() } });
  }
}

return articles.slice(0, 20);

