// Filter high-signal articles (relevance >= 7)
const items = $input.all();
const highSignal = [];

for (const item of items) {
  try {
    const text = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const cleaned = text.replace(/```json\n?|```\n?/g, '').trim();
    const analysis = JSON.parse(cleaned);
    if (analysis.relevance >= 7) {
      highSignal.push({ json: { ...item.json, analysis } });
    }
  } catch (e) {}
}

return highSignal.length > 0 ? highSignal : [{ json: { skip: true } }];

// Format for Telegram notification
const items = $input.all().filter(i => !i.json.skip);
if (items.length === 0) return [];

let message = `*RSS Intelligence* (${items.length} high-signal)\n\n`;
for (const item of items) {
  const a = item.json.analysis || {};
  const title = (item.json.title || '').replace(/[_*\[\]()~`>#+=|{}.!-]/g, ' ');
  message += `\u2022 *[${a.relevance}/10]* ${title}\n`;
  if (a.insight) message += `  _${a.insight}_\n`;
  message += `  ${item.json.link}\n\n`;
}

return [{ json: { message: message.slice(0, 4000) } }];
